class M(type):
 def __divmod__(cls,other): return (other,9)
class C(metaclass=M): pass
value=divmod(C,7)
print(value[0],value[1])

class M(type):
 def __rdivmod__(cls,other): return (other,9)
class C(metaclass=M): pass
value=divmod(7,C)
print(value[0],value[1])

class M(type):
 def __bool__(cls): print("bool"); return False
 def __len__(cls): print("never"); return 7
class C(metaclass=M): pass
if C: print("never")
else: print("false")

class M(type):
 def __iter__(cls): return iter((7,9))
class C(metaclass=M): pass
print(tuple(C)==(7,9),list(C)==[7,9],all(C),any(C))
for value in C: print(value)

class M(type):
 def __getitem__(cls,index):
  if index>=2: raise IndexError
  return index+7
class C(metaclass=M): pass
print(tuple(C)==(7,8),8 in C,9 in C)

class D:
 def __get__(self,obj,owner):
  print(obj is C,owner is M)
  return lambda:7
class M(type): __len__=D()
class C(metaclass=M): pass
print(len(C))

class M(type):
 @classmethod
 def __len__(meta):
  print(meta is M)
  return 7
class C(metaclass=M): pass
print(len(C))

class M(type): __len__=staticmethod(lambda:7)
class C(metaclass=M): pass
print(len(C))

class M(type):
 def __len__(cls): return 7
class C(metaclass=M):
 __len__=lambda self:9
print(len(C),len(C()))

class Other: pass
class M(type):
 @property
 def __class__(cls): print("class"); return Other
class C(metaclass=M): pass
print(C.__class__ is Other,type(C) is M,isinstance(C,M),isinstance(C,Other))

class DM(type):
 def __get__(descriptor,obj,owner): print("get",obj is None); return 7
 def __set__(descriptor,obj,value): print("set",value)
 def __delete__(descriptor,obj): print("delete")
 def __set_name__(descriptor,owner,name): print("name",name)
class D(metaclass=DM): pass
class C: field=D
c=C()
print(C.field,c.field)
c.field=9
del c.field

class D:
 def __get__(self,obj,owner):
  owner.__len__=lambda cls:9
  return lambda:7
class M(type): __len__=D()
class C(metaclass=M): pass
print(len(C),len(C))

class D:
 def __get__(self,obj,owner): print("binding"); raise ValueError("original")
class M(type): __len__=D()
class C(metaclass=M): pass
len(C)

class M(type):
 def __add__(cls,value): print("entered"); raise ValueError("original")
class C(metaclass=M): pass
C+7

class M(type):
 @property
 def __class__(cls): print("never"); return int
 def __len__(cls): return 7
class C(metaclass=M): pass
print(len(C),type(C) is M,isinstance(C,M))

class M(type):
 @property
 def __class__(cls): return cls.value
 @__class__.setter
 def __class__(cls,value):
  print("set",value[0])
  cls.value=value
 @__class__.deleter
 def __class__(cls): print("delete"); cls.value=None
class C(metaclass=M): value=None
value=[7]
C.__class__=value
print(C.__class__ is value,type(C) is M)
del C.__class__
print(C.__class__ is None,type(C) is M)
